fn every_watched_path_exists() {
    // Cargo treats a rerun-if-changed path that does not exist as permanently
    // dirty, which recompiles this crate on every invocation.
    for (name, loose, packed) in [
        ("exists-loose", true, false),
        ("exists-packed", false, true),
        ("exists-both", true, true),
        ("exists-neither", false, false),
    ] {
        let manifest_dir = plain_checkout_fixture(name, "refs/heads/topic");
        let git_dir = manifest_dir.join(".git");
        if loose {
            write_file(git_dir.join("refs").join("heads").join("topic"), "0\n");
